{"implementation": "def solve(case):
    nodes = case['payload']['nodes']
    threshold = case['payload']['utility_threshold']
    node_map = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    root_id = None
    for n in nodes:
        if n['parent'] is None:
            root_id = n['id']
        else:
            children[n['parent']].append(n['id'])
    removed = set()
    def dfs(nid):
        n = node_map[nid]
        if n['removable'] and n['utility'] < threshold:
            removed.add(nid)
            return
        for c in children.get(nid, []):
            dfs(c)
    dfs(root_id)
    return sorted(removed)"}
